import json
from pathlib import Path

ПОРОГ = 100


def обійти(вузол, шлях):
    # bool є підкласом int у Python, тому виключаємо true/false явно
    if isinstance(вузол, bool):
        return
    if isinstance(вузол, (int, float)):
        if вузол > ПОРОГ:
            yield шлях, вузол
        return
    if isinstance(вузол, dict):
        for ключ, значення in вузол.items():
            yield from обійти(значення, шлях + [str(ключ)])
    elif isinstance(вузол, list):
        for індекс, значення in enumerate(вузол):
            yield from обійти(значення, шлях + [str(індекс)])


def main():
    шлях_до_файлу = Path("дані") / "структура.json"
    with open(шлях_до_файлу, encoding="utf-8") as f:
        дані = json.load(f)

    знайдено = 0
    for шлях, значення in обійти(дані, []):
        print(f"{'.'.join(шлях)} = {значення}")
        знайдено += 1
    print(f"Знайдено: {знайдено}")


if __name__ == "__main__":
    main()

